    Text = "Tôi không nói gì"
  },
  AvgVideoCaption_149926_Content_42 = {
    Text = "Vì tôi thậm chí không thể mở miệng ra được"
  },
  AvgVideoCaption_149926_Content_43 = {
    Text = "Nhưng nó nói:"
  },
  AvgVideoCaption_149926_Content_44 = {
    Text = "『Không sao』"
  },
  AvgVideoCaption_149926_Content_45 = {
    Text = "『Ta sẽ dạy ngươi một thứ ngôn ngữ』"
  },
  AvgVideoCaption_149926_Content_46 = {
    Text = "『Nói ra nó, ngươi sẽ không bao giờ lạnh nữa』"
  },
  AvgVideoCaption_149926_Content_47 = {
    Text = "Vậy là tôi"
  },
  AvgVideoCaption_149926_Content_48 = {
    Text = "Đã học được câu nói dối đầu tiên"
  },
  AvgVideoCaption_149926_Content_49 = {
    Text = "Tôi dùng câu nói dối đó"
  },
  AvgVideoCaption_149926_Content_5 = {
    Text = "Tôi sẽ cho ông tất cả những gì tôi có"
  },
  AvgVideoCaption_149926_Content_50 = {
    Text = "Gõ cửa ngôi nhà nông dân đầu tiên"
  },
  AvgVideoCaption_149926_Content_51 = {
    Text = "Lừa được một quả táo"
  },
  AvgVideoCaption_149926_Content_52 = {
    Text = "Tôi chỉ cắn một miếng"
  },
  AvgVideoCaption_149926_Content_53 = {
    Text = "Phần còn lại"
  },
  AvgVideoCaption_149926_Content_54 = {
    Text = "Đều dành cho giọng nói đó"
  },
  AvgVideoCaption_149926_Content_55 = {
    Text = "Bạn có biết không"
  },
  AvgVideoCaption_149926_Content_56 = {
    Text = "Khi người ta sắp chết cóng"
  },
  AvgVideoCaption_149926_Content_57 = {
    Text = "Toàn thân sẽ nóng bừng lên"
  },
  AvgVideoCaption_149926_Content_58 = {
    Text = "Ấm hơn tất cả mọi lò sưởi trên đời"
  },
  AvgVideoCaption_149926_Content_59 = {
    Text = "Kể từ khoảnh khắc đó"
  },
  AvgVideoCaption_149926_Content_6 = {
    Text = "Đừng bán tôi đi, được không?"
  },
  AvgVideoCaption_149926_Content_60 = {
    Text = "Tôi chưa bao giờ cảm thấy lạnh nữa"
  },
  AvgVideoCaption_149926_Content_61 = {Text = "Nó nói"},
  AvgVideoCaption_149926_Content_62 = {
    Text = "Nó chỉ \"dạy\" tôi thôi"
  },
  AvgVideoCaption_149926_Content_63 = {
    Text = "Tôi học rất nhanh"
  },
  AvgVideoCaption_149926_Content_64 = {
    Text = "Những thứ lừa được ngày càng nhiều hơn"
  },
  AvgVideoCaption_149926_Content_65 = {
    Text = "Như những ngọn đồi nhỏ"
  },
  AvgVideoCaption_149926_Content_66 = {
    Text = "Chất đầy cả căn nhà"
  },
  AvgVideoCaption_149926_Content_67 = {
    Text = "Nhưng về sau"
  },
  AvgVideoCaption_149926_Content_68 = {
    Text = "Tôi dần dần nhận ra"
  },
  AvgVideoCaption_149926_Content_69 = {
    Text = "Mỗi lần nói dối"
  },
  AvgVideoCaption_149926_Content_7 = {Text = "Xin ông"},
  AvgVideoCaption_149926_Content_70 = {
    Text = "Tôi lại quên đi một chút hình dáng nguyên bản của mình"
  },
  AvgVideoCaption_149926_Content_71 = {
    Text = "Thứ quên đi đầu tiên"
  },
  AvgVideoCaption_149926_Content_72 = {
    Text = "Là tiếng cha đập bàn lúc say rượu"
  },
  AvgVideoCaption_149926_Content_73 = {
    Text = "Rồi đến khuôn mặt khóc của mẹ"
  },
  AvgVideoCaption_149926_Content_74 = {
    Text = "Sau đó nữa"
  },
  AvgVideoCaption_149926_Content_75 = {
    Text = "Là chính cái tên của tôi"
  },
  AvgVideoCaption_149926_Content_76 = {
    Text = "Tôi cũng đã từng nghĩ"
  },
  AvgVideoCaption_149926_Content_77 = {
    Text = "Cứ tiếp tục như vậy liệu có ổn không"
  },
  AvgVideoCaption_149926_Content_78 = {
    Text = "Nhưng mỗi lần tôi vừa có ý nghĩ đó"
  },
  AvgVideoCaption_149926_Content_79 = {
    Text = "Nó lại khẽ thì thầm bên tai tôi—"
  },
  AvgVideoCaption_149926_Content_8 = {
    Text = "Hãy thương xót tôi với…"
  },
  AvgVideoCaption_149926_Content_80 = {
    Text = "『Lạnh không? Muốn ấm hơn một chút không?』"
  },
  AvgVideoCaption_149926_Content_81 = {
    Text = "Rồi tôi lại"
  },
  AvgVideoCaption_149926_Content_82 = {
    Text = "nói thêm một câu nữa"
  },
  AvgVideoCaption_149926_Content_83 = {
    Text = "rồi thêm một câu, rồi lại thêm một câu"
  },
  AvgVideoCaption_149926_Content_84 = {
    Text = "thêm một câu nữa, câu này nối tiếp câu kia"
  },
  AvgVideoCaption_149926_Content_85 = {
    Text = "thật đơn giản, thật nhẹ nhàng"
  },
  AvgVideoCaption_149926_Content_86 = {
    Text = "dễ dàng tuôn chảy ra từ trong tuyết"
  },
  AvgVideoCaption_149926_Content_87 = {
    Text = "nhưng lại ấm áp và ngọt ngào"
  },
  AvgVideoCaption_149926_Content_88 = {
    Text = "tôi là ai vậy,"
  },
  AvgVideoCaption_149926_Content_89 = {
    Text = "tôi có phải là chính mình không?"
  },
  AvgVideoCaption_149926_Content_9 = {
    Text = "Từ nhỏ tôi đã không được yêu thương"
  },
  AvgVideoCaption_149926_Content_90 = {
    Text = "Giọng nói dưới tuyết"
  },
  AvgVideoCaption_149926_Content_91 = {
    Text = "thực ra ngay từ đầu"
  },
  AvgVideoCaption_149926_Content_92 = {
    Text = "vốn là giọng nói của chính tôi phải không?"
  },
  AvgVideoCaption_149926_Content_93 = {
    Text = "Ôi thôi, đừng chạy nào, thưa ngài"
  },
  AvgVideoCaption_149926_Content_94 = {
    Text = "chạy cũng không kịp nữa rồi đâu"
  },
  AvgVideoCaption_149926_Content_95 = {
    Text = "tay và chân của ngài"
  },
  AvgVideoCaption_149926_Content_96 = {
    Text = "đã cứng đờ vì lạnh từ lâu rồi"
  },
  AvgVideoCaption_149926_Content_97 = {
    Text = "Cần chúng tôi giúp ngài sưởi ấm không?"
  },
  AvgVideoCaption_149926_Content_98 = {
    Text = "Đừng khóc nào"
  },
  AvgVideoCaption_149926_Content_99 = {
    Text = "tôi đã thử rồi"
  },
  AvgVideoCaption_18618_Content_1 = {
    Text = "Ở sâu trong phòng kín, quái vật trắng tinh đứng im lìm."
  },
  AvgVideoCaption_18619_Content_1 = {
    Text = "Ánh mắt điên loạn dần dần phai nhạt trong đôi mắt của lơ-tan, thay vào đó là một màu bạc mờ ảm đạm."
  },
  AvgVideoCaption_18619_Content_2 = {
    Text = "Lơ-tan, sau khi tỉnh táo lại, dường như đang chịu đựng cơn đau đầu dữ dội. Cô chống tay lên trán, rồi cúi đầu xuống."
  },
  AvgVideoCaption_18620_Content_1 = {
    Text = "Khi câu nói của cô vừa dứt, tất cả những tồn tại vượt quá lý thường đều biến mất trong nháy mắt."
  },
  AvgVideoCaption_18621_Content_1 = {
    Text = "Cô ấy nâng tay lên, lau sạch một tấm kính trước mặt cô ấy."
  },
  AvgVideoCaption_18622_Content_1 = {
    Text = "Ánh hoàng hôn vàng rực xuyên qua mặt đồng hồ lớn trong suốt của tháp chuông, rải xuống người cô gái."
  },
  AvgVideoCaption_18623_Content_1 = {
    Text = "Lại thêm một lần nữa, chỉ còn lại một mình thôi."
  },
  AvgVideoCaption_18624_Content_1 = {
    Text = "Sau khoảnh khắc, vẻ ngoài kỳ quái tan biến."
  },
  AvgVideoCaption_18625_Content_1 = {
    Text = "Trước những thực thể to lớn và bí ẩn.."
  },
  AvgVideoCaption_18625_Content_10 = {
    Text = "Khi nghe thấy từ đó, âm thanh ong ong dữ dội cùng cơn đau đâm thẳng vào sâu trong não."
  },
  AvgVideoCaption_18625_Content_11 = {
    Text = "Dạ dày như bị đảo lộn dữ dội, mùi hôi thối của chất nôn xộc thẳng vào khoang mũi."
  },
  AvgVideoCaption_18625_Content_2 = {
    Text = "Con người, thật nhỏ bé."
  },
  AvgVideoCaption_18625_Content_3 = {
    Text = "Có phải là mơ không?"
  },
  AvgVideoCaption_18625_Content_4 = {
    Text = "Cảm giác bất an mạnh mẽ dâng lên trong ngực."
  },
  AvgVideoCaption_18625_Content_5 = {
    Text = "—Lăng mộ Đại học Misag, Lễ trao chìa khóa bạc—"
  },
  AvgVideoCaption_18625_Content_6 = {
    Text = "\"……Đại học Misag là tiền phong trong cuộc chiến chống lại @2……\""
  },
  AvgVideoCaption_18625_Content_7 = {
    Text = "\"... trở thành điều tra viên của Đại học Misag,\""
  },
  AvgVideoCaption_18625_Content_8 = {
    Text = "\"có nghĩa là phần đời còn lại của các ngươi sẽ sống cùng với cái chết và sự điên rồ…\""
  },
  AvgVideoCaption_18625_Content_9 = {
    Text = "\"Trong mười năm gần đây, sự lan rộng @2…\""
  },
  AvgVideoCaption_18626_Content_1 = {
    Text = "Có thể đổi lấy sự an toàn của mọi người hiện tại, tôi cũng cảm thấy mãn nguyện."
  },
  AvgVideoCaption_18626_Content_10 = {
    Text = "Cảm giác ẩm ướt truyền đến đầu ngón tay, nhưng không có cảm giác chân thực khi chạm vào."
  },
  AvgVideoCaption_18626_Content_11 = {
    Text = "Một phần nhỏ thực tại tan biến dưới đầu ngón tay cô, biến mất khỏi thế giới mãi mãi."
  },
  AvgVideoCaption_18626_Content_2 = {
    Text = "Tôi sẽ không để bị kiểm soát nữa."
  },
  AvgVideoCaption_18626_Content_3 = {
    Text = "Sẽ không gây thương hại cho bất kỳ ai nữa."
  },
  AvgVideoCaption_18626_Content_4 = {
    Text = "Tôi sẽ không bao giờ để bạn bè phải hy sinh vì mình nữa."
  },
  AvgVideoCaption_18626_Content_5 = {
    Text = "Dựa vào tiếng chuông để che đậy, Ai Jī Sī đã khéo léo mở ra cánh cửa kính lẽ ra đã bị niêm phong."
  },
  AvgVideoCaption_18626_Content_6 = {
    Text = "Xin lỗi Jenkin dùm tôi."
  },
  AvgVideoCaption_18626_Content_7 = {
    Text = "Nói với cô ấy là chúng mình sẽ mãi là bạn bè."
  },
  AvgVideoCaption_18626_Content_8 = {
    Text = "Ai Jī Sī nhắm mắt lại, chỉ cảm thấy mình trở nên rất nhẹ, rất nhẹ. Phía sau cô ấy, Ramona đưa tay về phía bầu trời đêm một cách khẩn thiết."
  },
  AvgVideoCaption_18626_Content_9 = {
    Text = "Liên hệ,  nắm chặt."
  },
  AvgVideoCaption_22146_Content_1 = {
    Text = "Thảm họa khủng khiếp đã đến"
  },
  AvgVideoCaption_22146_Content_2 = {
    Text = "\"rỗng rỗng\""
  },
  AvgVideoCaption_22146_Content_3 = {
    Text = "Nó nuốt chửng tất cả"
  },
  AvgVideoCaption_22146_Content_4 = {
    Text = "Thậm chí ký ức cũng không thể thoát khỏi bàn tay của hắn"
  },
  AvgVideoCaption_22146_Content_5 = {
    Text = "Sau hàng thế kỷ, chúng ta cuối cùng đã tìm thấy điểm đột phá ——"
  },
  AvgVideoCaption_22146_Content_6 = {
    Text = "\"bạc tâm\""
  },
  AvgVideoCaption_22146_Content_7 = {
    Text = "Nó có thể gọi dậy linh hồn đã mất"
  },
  AvgVideoCaption_22146_Content_8 = {
    Text = "Những linh hồn này là hy vọng cuối cùng của chúng ta"
  },
  AvgVideoCaption_22146_Content_9 = {
    Text = "Ít ra, chúng tôi mong là như vậy…"
  },
  AvgVideoCaption_24281_Content_1 = {
    Text = "Cuối cùng cũng đón được khoảnh khắc nở rộ."
  },
  AvgVideoCaption_24724_Content_1 = {
    Text = "Việc thất bại bao nhiêu lần không quan trọng"
  },
  AvgVideoCaption_24724_Content_2 = {
    Text = "Dù quay lại bao nhiêu lần, tôi cũng nhất định sẽ tìm thấy nó"
  },
  AvgVideoCaption_24724_Content_3 = {
    Text = "Giải cứu thế giới này"
  },
  AvgVideoCaption_24724_Content_4 = {
    Text = "Phương pháp cứu bạn"
  },
  AvgVideoCaption_36151_Content_1 = {
    Text = "Lối ra, lối ra ở đó…"
  },
  AvgVideoCaption_36151_Content_10 = {
    Text = "Lắng nghe chủ ta!"
  },
  AvgVideoCaption_36151_Content_11 = {
    Text = "Vì sao phải nghe theo!"
  },
  AvgVideoCaption_36151_Content_12 = {
    Text = "Trở về với Đấng Chủ Tể"
  },
  AvgVideoCaption_36151_Content_13 = {
    Text = "Vì sao phải khuất phục!"
  },
  AvgVideoCaption_36151_Content_14 = {
    Text = "Hy sinh! Tái tạo thần quốc ——"
  },
  AvgVideoCaption_36151_Content_15 = {
    Text = "Thần quốc gì, thần linh gì… có liên quan gì đến ta!"
  },
  AvgVideoCaption_36151_Content_16 = {
    Text = "Tự sát! Trả lại chủ nhân của ta ——"
  },
  AvgVideoCaption_36151_Content_17 = {
    Text = "Rời khỏi đây. Chúng ta cùng…… rời khỏi đây!"
  },
  AvgVideoCaption_36151_Content_2 = {
    Text = "Mẹ thần, sao lại đi?"
  },
  AvgVideoCaption_36151_Content_3 = {
    Text = "Đừng… Tôi không muốn trở thành thần mẫu"
  },
  AvgVideoCaption_36151_Content_4 = {
    Text = "Tôi không muốn trở thành tế phẩm.."
  },
  AvgVideoCaption_36151_Content_5 = {
    Text = "Thần quốc sẽ hóa thân vào ngươi"
  },
  AvgVideoCaption_36151_Content_6 = {
    Text = "Còn bao xa? Còn bao lâu?"
  },
  AvgVideoCaption_36151_Content_7 = {
    Text = "Thời khắc chính vị đã đến——"
  },
  AvgVideoCaption_36151_Content_8 = {
    Text = "Đã… không còn kịp nữa sao?"
  },
  AvgVideoCaption_36151_Content_9 = {
    Text = "Nhưng… tại sao?!"
  },
  AvgVideoCaption_45044_Content_1 = {
    Text = "Dịch bệnh vô hình đã giáng xuống"
  },
  AvgVideoCaption_45044_Content_10 = {
    Text = "\"Bạn có sẵn sàng hiến dâng thịt máu của mình cho chúng tôi không?\""
  },
  AvgVideoCaption_45044_Content_11 = {
    Text = "\"Would you be willing to sacrifice your life for us?\""
  },
  AvgVideoCaption_45044_Content_12 = {
    Text = "\"Thần Cha đã rơi lệ vì chúng con, những người con của Ngài.\""
  },
  AvgVideoCaption_45044_Content_13 = {
    Text = "\"Ngài muốn những người cao quý trong chúng tôi trở thành Người đại diện cho ý chí của Ngài\""
  },
  AvgVideoCaption_45044_Content_14 = {
    Text = "\"Xóa bỏ khổ nạn trên mặt đất này.\""
  },
  AvgVideoCaption_45044_Content_15 = {
    Text = "Tôi là đại diện của Đấng Tối Cao"
  },
  AvgVideoCaption_45044_Content_16 = {
    Text = "Tất nhiên sẽ hết sức"
  },
  AvgVideoCaption_45044_Content_17 = {
    Text = "\"Tại sao, Đức Giám mục, tại sao hôm nay không có phúc lành?\""
  },
  AvgVideoCaption_45044_Content_18 = {
    Text = "\"Tại sao bạn không tiếp tục, tại sao không cứu chúng tôi!\""
  },
  AvgVideoCaption_45044_Content_19 = {
    Text = "\"Sao bạn có thể vô năng như vậy?\""
  },
  AvgVideoCaption_45044_Content_2 = {
    Text = "Nó mang lại cái chết, gây ra tuyệt vọng"
  },
  AvgVideoCaption_45044_Content_20 = {
    Text = "\"Bạn đã bỏ rơi chúng tôi, để mặc nỗi đau lan rộng!\""
  },
  AvgVideoCaption_45044_Content_21 = {
    Text = "\" Tôi muốn ban phúc lành và sống tiếp! \""
  },
  AvgVideoCaption_45044_Content_22 = {
    Text = "\"không đủ, không đủ, không đủ!\""
  },
  AvgVideoCaption_45044_Content_23 = {
    Text = "Cuộc đời tôi"
  },
  AvgVideoCaption_45044_Content_24 = {
    Text = "Đều cam kết giải thoát các bạn khỏi những đau khổ"
  },
  AvgVideoCaption_45044_Content_25 = {
    Text = "Người chăn linh hồn"
  },
  AvgVideoCaption_45044_Content_26 = {
    Text = "Mọi thứ, đều là vì phúc lợi của các bạn"
  },
  AvgVideoCaption_45044_Content_3 = {
    Text = "Các con của Cha thần"
  },
  AvgVideoCaption_45044_Content_4 = {
    Text = "Anh chị em tôi"
  },
  AvgVideoCaption_45044_Content_5 = {
    Text = "Sự khổ nạn của các bạn, tôi thấu hiểu"
  },
  AvgVideoCaption_45044_Content_6 = {
    Text = "Tôi sẵn sàng đánh đổi mọi thứ"
  },
  AvgVideoCaption_45044_Content_7 = {
    Text = "Chỉ mong các bạn không còn đau khổ"
  },
  AvgVideoCaption_45044_Content_8 = {
    Text = "\"Giám mục Salvador, hôm nay ngài có ban phúc lành cho chúng tôi không?\""
  },
  AvgVideoCaption_45044_Content_9 = {
    Text = "\"Quý vị Giám mục Salvador, ngài có cứu chúng tôi không?\""
  },
  AvgVideoCaption_50040_Content_1 = {
    Text = "Sinh sản, là điều trong sa mạc nguyên thủy này"
  },
  AvgVideoCaption_50040_Content_10 = {
    Text = "Hoàn toàn hòa quyện với tôi"
  },
  AvgVideoCaption_50040_Content_11 = {
    Text = "Hãy sinh con cùng tôi"
  },
  AvgVideoCaption_50040_Content_12 = {
