    Text = "Các tuyến đường trong thế giới không thể dẫn đến hạnh phúc"
  },
  AvgVideoCaption_84327_Content_94 = {
    Text = "Chỉ có những ai hy sinh tất cả mới có quyền nhìn thấy Vùng đất thần thánh"
  },
  AvgVideoCaption_84327_Content_95 = {
    Text = "<Red:Vậy, hãy quy y nó！>"
  },
  AvgVideoCaption_84327_Content_96 = {
    Text = "<Red:Hiến dâng mọi thứ！>"
  },
  AvgVideoCaption_84327_Content_97 = {
    Text = "Cuối cùng, sau khi dâng hiến mọi thứ, tôi đã nhìn thấy…"
  },
  AvgVideoCaption_84327_Content_98 = {
    Text = "Sự tồn tại hùng vĩ, bao la, không thể mô tả..."
  },
  AvgVideoCaption_84327_Content_99 = {
    Text = "Bộ não nông cạn của con người không thể hiểu được biển cả sâu thẳm"
  },
  AvgVideoCaption_90244_Content_1 = {Text = "Ha…"},
  AvgVideoCaption_90244_Content_10 = {
    Text = "Nắm chặt quá sâu... lông vũ đều bị máu dính chặt"
  },
  AvgVideoCaption_90244_Content_100 = {
    Text = "Trong bản thảo có rất nhiều nơi mà chúng ta chưa đi qua, thực sự muốn đi xem tất cả"
  },
  AvgVideoCaption_90244_Content_101 = {
    Text = "Sẽ đi, chắc chắn"
  },
  AvgVideoCaption_90244_Content_102 = {
    Text = "Cuối cùng, hiệp sĩ đã đưa công chúa trở lại đất nước"
  },
  AvgVideoCaption_90244_Content_103 = {
    Text = "Vô số hoa được ném rải trên con đường chào đón họ"
  },
  AvgVideoCaption_90244_Content_104 = {
    Text = "Danh tiếng của hiệp sĩ lan rộng khắp cả nước"
  },
  AvgVideoCaption_90244_Content_105 = {
    Text = "À, đã kết thúc rồi"
  },
  AvgVideoCaption_90244_Content_106 = {
    Text = "Lần nào cũng muốn biết điều gì sẽ xảy ra sau khi câu chuyện kết thúc?"
  },
  AvgVideoCaption_90244_Content_107 = {
    Text = "Anh trai, anh nói hiệp sĩ sau này thế nào rồi"
  },
  AvgVideoCaption_90244_Content_108 = {
    Text = "Liệu anh ta sẽ nhận được vinh quang, sự giàu có và tình yêu của công chúa không?"
  },
  AvgVideoCaption_90244_Content_109 = {
    Text = "Tôi không biết..."
  },
  AvgVideoCaption_90244_Content_11 = {
    Text = "Trước tiên, tôi sẽ dọn sạch những thứ bẩn thỉu này"
  },
  AvgVideoCaption_90244_Content_110 = {
    Text = "Nhưng ít nhất anh ta đã nhận được vinh quang"
  },
  AvgVideoCaption_90244_Content_111 = {
    Text = "Vậy, anh ấy đã cứu công chúa từ nơi xa xôi"
  },
  AvgVideoCaption_90244_Content_112 = {
    Text = "Nhà vua chắc chắn sẽ ban thưởng cho anh ấy chứ?"
  },
  AvgVideoCaption_90244_Content_113 = {
    Text = "Đúng vậy, nhà vua chắc phải là người rộng rãi"
  },
  AvgVideoCaption_90244_Content_114 = {
    Text = "Anh ta mang công chúa thoát khỏi lâu đài, và đã đi qua nhiều nơi"
  },
  AvgVideoCaption_90244_Content_115 = {
    Text = "Có thể công chúa cũng sẽ yêu anh ta sao?"
  },
  AvgVideoCaption_90244_Content_116 = {
    Text = "Ừm... Có lý"
  },
  AvgVideoCaption_90244_Content_117 = {
    Text = "Dù hiệp sĩ không muốn gì cả"
  },
  AvgVideoCaption_90244_Content_118 = {
    Text = "Nhưng dù sao anh ta vẫn sẽ nhận được tất cả"
  },
  AvgVideoCaption_90244_Content_119 = {
    Text = "Quả nhiên những người can đảm cuối cùng nhất định sẽ... đạt được... tất cả..."
  },
  AvgVideoCaption_90244_Content_12 = {
    Text = "...Rất đau phải không? Xin lỗi, mình sẽ nhẹ nhàng hơn"
  },
  AvgVideoCaption_90244_Content_120 = {
    Text = "(Đã ngủ rồi à... chạy trốn những ngày này thực sự quá mệt mỏi)"
  },
  AvgVideoCaption_90244_Content_121 = {
    Text = "(Đã rơi nhiều lông rồi, tiếc quá... Ừm? Phản này vẫn nguyên vẹn)"
  },
  AvgVideoCaption_90244_Content_122 = {
    Text = "(Để lại đây, khi có thời gian sẽ làm một chiếc vòng cổ cho Polyx nhé)"
  },
  AvgVideoCaption_90244_Content_123 = {
    Text = "(Trăng tròn quá, bầu trời đầy sao đẹp làm sao)"
  },
  AvgVideoCaption_90244_Content_124 = {
    Text = "(Giống như trong sách... người dũng cảm sẽ có được tất cả chăng?)"
  },
  AvgVideoCaption_90244_Content_125 = {
    Text = "(Câu chuyện trong sách, sẽ không lừa chứ...)"
  },
  AvgVideoCaption_90244_Content_126 = {
    Text = "(Chúc ngủ ngon, hiệp sĩ Polyx)"
  },
  AvgVideoCaption_90244_Content_13 = {
    Text = "Cũng, cũng ổn mà"
  },
  AvgVideoCaption_90244_Content_14 = {
    Text = "So với cảm giác phẫu thuật mở ngực trong lễ cải tạo, từng chút khắc lên nội tạng"
  },
  AvgVideoCaption_90244_Content_15 = {
    Text = "Đau chút này không là gì cả"
  },
  AvgVideoCaption_90244_Content_16 = {
    Text = "...Đúng vậy, trong số chúng ta, luôn có bạn chịu đựng nhiều đau khổ hơn"
  },
  AvgVideoCaption_90244_Content_17 = {
    Text = "(Ái, lỡ nói sai...)"
  },
  AvgVideoCaption_90244_Content_18 = {
    Text = "Mọi thứ đã qua rồi, anh trai"
  },
  AvgVideoCaption_90244_Content_19 = {
    Text = "Trước đây chúng ta không thể quyết định bất cứ điều gì, nhưng sau này chúng ta sẽ tự do!"
  },
  AvgVideoCaption_90244_Content_2 = {
    Text = "Chạy đến đây con quái vật kia hẳn sẽ không truy đuổi nữa"
  },
  AvgVideoCaption_90244_Content_20 = {
    Text = "Hãy kể lại cho tôi nghe câu chuyện trong bản thảo tay nữa"
  },
  AvgVideoCaption_90244_Content_21 = {
    Text = "Cũng như sau mỗi lễ cải Đạo trước đây, nghe chuyện thì vết thương sẽ không đau nữa"
  },
  AvgVideoCaption_90244_Content_22 = {Text = "Tốt"},
  AvgVideoCaption_90244_Content_23 = {
    Text = "Vậy... hãy kể về cuộc phiêu lưu của hiệp sĩ huyền thoại nhé"
  },
  AvgVideoCaption_90244_Content_24 = {
    Text = "Cuối cùng, hiệp sĩ tìm thấy quái vật trong Bóng tối của lâu đài"
  },
  AvgVideoCaption_90244_Content_25 = {
    Text = "Chất vấn nó về nơi ở của công chúa"
  },
  AvgVideoCaption_90244_Content_26 = {
    Text = "Quái vật màu xanh đậm đó khổng lồ như người khổng lồ"
  },
  AvgVideoCaption_90244_Content_27 = {
    Text = "Phát ra tiếng gầm quái dị đáng sợ từ sâu trong thân thể đang run rẩy"
  },
  AvgVideoCaption_90244_Content_28 = {
    Text = "Nó giơ cao cái rìu"
  },
  AvgVideoCaption_90244_Content_29 = {
    Text = "Ánh sáng lạnh như vầng trăng mới cắt qua sảnh đường tĩnh lặng"
  },
  AvgVideoCaption_90244_Content_3 = {
    Text = "Nghỉ ngơi một chút, ssss..."
  },
  AvgVideoCaption_90244_Content_30 = {
    Text = "Người kỵ sĩ dũng cảm đứng yên lặng"
  },
  AvgVideoCaption_90244_Content_31 = {
    Text = "Chỉ có một cái đầu tóc vàng nhẹ nhàng lay động trong gió"
  },
  AvgVideoCaption_90244_Content_32 = {
    Text = "Rìu rống mạnh chém xuống, nhưng đột ngột dừng lại trước khi chạm vào cổ hiệp sĩ"
  },
  AvgVideoCaption_90244_Content_33 = {
    Text = "\"Đây là một cú đánh vào lời hứa mà bạn đã giữ.\""
  },
  AvgVideoCaption_90244_Content_34 = {
    Text = "Quái vật khe khẽ nói, giọng vo vo như những miếng sắt gỉ sét cọ xát nhau"
  },
  AvgVideoCaption_90244_Content_35 = {
    Text = "\"Bạn không chùn bước trước cuộc đấu hôm nay, xứng đáng với danh hiệu của một kỵ sĩ.\""
  },
  AvgVideoCaption_90244_Content_36 = {
    Text = "Giống như chúng ta không bị đánh bại bởi quái vật hôm nay!"
  },
  AvgVideoCaption_90244_Content_37 = {
    Text = "Nhát chém thứ hai rơi xuống lần nữa"
  },
  AvgVideoCaption_90244_Content_38 = {
    Text = "Vẫn dừng lại chỉ trước một chút, chỉ làm xước bề mặt da của hiệp sĩ..."
  },
  AvgVideoCaption_90244_Content_39 = {
    Text = "Pollux, ngay cả những lông vũ lớn nhất cũng bị gãy"
