  AvgVideoCaption_90244_Content_4 = {
    Text = "Pollux! Đôi cánh của anh bị thương rất nặng"
  },
  AvgVideoCaption_90244_Content_40 = {
    Text = "Bình thường bạn chăm sóc chúng nhiều như vậy..."
  },
  AvgVideoCaption_90244_Content_41 = {
    Text = "Không sao đâu, lông vũ sẽ mọc lại, đây chính là huân chương của tự do"
  },
  AvgVideoCaption_90244_Content_42 = {
    Text = "Giống như hiệp sĩ đúng không?"
  },
  AvgVideoCaption_90244_Content_43 = {
    Text = "Ừm... Vết thương xung quanh đã được lau sạch rồi"
  },
  AvgVideoCaption_90244_Content_44 = {
    Text = "Lông của bạn đã rối, để tôi chải nó cho bạn"
  },
  AvgVideoCaption_90244_Content_45 = {
    Text = "Cảm ơn, Hiệp sĩ Castor"
  },
  AvgVideoCaption_90244_Content_46 = {
    Text = "Xin hãy tiếp tục tường thuật câu chuyện phiêu lưu đi!"
