  AvgVideoCaption_90244_Content_47 = {
    Text = "Được rồi, tôi hiểu rồi"
  },
  AvgVideoCaption_90244_Content_48 = {
    Text = "Trong mắt quái vật lóe lên ánh sáng biết ơn"
  },
  AvgVideoCaption_90244_Content_49 = {
    Text = "\"Đây là trừng phạt cho việc bạn đã cứu con của tôi, nhưng lại đánh cắp chìa khóa từ cô ấy, lẻn vào lâu đài.\""
  },
  AvgVideoCaption_90244_Content_5 = {
    Text = "Chết tiệt, vừa rồi tất cả đều do tôi không chặn được nó, nếu tôi đã..."
  },
  AvgVideoCaption_90244_Content_50 = {
    Text = "Hiệp sĩ nhận ra sự thật"
  },
  AvgVideoCaption_90244_Content_51 = {
    Text = "\"Cô gái ngã xuống nước đó chính là con của bạn!\""
  },
  AvgVideoCaption_90244_Content_52 = {
    Text = "Quái vật gật đầu"
  },
  AvgVideoCaption_90244_Content_53 = {
    Text = "\"Chính xác, cú đánh cuối cùng sắp tới, đó là trận chiến thực sự của chúng ta.\""
  },
  AvgVideoCaption_90244_Content_54 = {
    Text = "Hiệp sĩ giơ kiếm lên, dùng mũi kiếm chỉ lên chào quái vật"
  },
  AvgVideoCaption_90244_Content_55 = {
    Text = "Vào lúc này, bóng dáng của quái vật đột nhiên biến mất"
  },
  AvgVideoCaption_90244_Content_56 = {
    Text = "Hiệp sĩ tiến tới một cách thận trọng"
  },
  AvgVideoCaption_90244_Content_57 = {
    Text = "Lâu đài vắng bóng người được phủ một lớp Bóng tối xoắn vặn"
  },
  AvgVideoCaption_90244_Content_58 = {
    Text = "Chỉ nghe thấy âm thanh hư ảo của quái vật lượn lờ bên tai anh ta"
  },
  AvgVideoCaption_90244_Content_59 = {
    Text = "「Kỵ sĩ dũng cảm, vì sao bạn kiên trì chiến đấu?」"
  },
  AvgVideoCaption_90244_Content_6 = {
    Text = "Thôi nào, đừng nói vậy, đây là lần đầu tiên chúng ta ra ngoài"
  },
  AvgVideoCaption_90244_Content_60 = {
    Text = "\"Là vì danh dự và sự ngưỡng mộ?\""
  },
  AvgVideoCaption_90244_Content_61 = {
    Text = "Một nhóm thường dân xuất hiện từ hư không, họ bao quanh hiệp sĩ từng lớp một"
  },
  AvgVideoCaption_90244_Content_62 = {
    Text = "Nhiều khuôn mặt nở nụ cười, không ngừng ca ngợi vinh quang của anh ấy"
  },
  AvgVideoCaption_90244_Content_63 = {
    Text = "Hiệp sĩ nhận ra sự kỳ lạ của những ảo ảnh"
  },
  AvgVideoCaption_90244_Content_64 = {
    Text = "Biểu hiện của anh ta không hề rung động, lập tức phá tan những bóng ảnh giả dối đó"
  },
  AvgVideoCaption_90244_Content_65 = {
    Text = "\"Vậy, có phải vì phần thưởng và tài sản?\""
  },
  AvgVideoCaption_90244_Content_66 = {
    Text = "Một người hầu khiêm tốn đến trước mặt kỵ sĩ"
  },
  AvgVideoCaption_90244_Content_67 = {
    Text = "Anh ta ôm tiền xu sáng chói và vương miện sang trọng khảm hồng ngọc"
  },
  AvgVideoCaption_90244_Content_68 = {
    Text = "Luồn cúi dâng lên cho kỵ sĩ"
  },
  AvgVideoCaption_90244_Content_69 = {
    Text = "Hiệp sĩ không nhìn vào chiếc vương miện tượng trưng cho sự thịnh vượng và quyền lực vô tận"
  },
  AvgVideoCaption_90244_Content_7 = {
    Text = "Còn nữa, chẳng phải đã chạy thoát suôn sẻ rồi sao? Vui lên chút đi, chúng ta đã rất giỏi rồi!"
  },
  AvgVideoCaption_90244_Content_70 = {
    Text = "Vung kiếm chém tan Ảo ảnh của kẻ hầu"
  },
  AvgVideoCaption_90244_Content_71 = {
    Text = "Giọng chói tai của quái vật tiếp tục nói, \"Ồ? Hay là, để giành được tình yêu của công chúa?\""
  },
  AvgVideoCaption_90244_Content_72 = {
    Text = "Hình dáng đẹp của công chúa xuất hiện trước hiệp sĩ"
  },
  AvgVideoCaption_90244_Content_73 = {
    Text = "Hàng mi dài của cô nàng khẽ chớp, ánh mắt mê man dựa vào lòng của hiệp sĩ"
  },
  AvgVideoCaption_90244_Content_74 = {
    Text = "Hiệp sĩ dùng một thanh kiếm chém vào ảo ảnh của công chúa,"
  },
  AvgVideoCaption_90244_Content_75 = {
    Text = "\"Không, không phải, tôi chiến đấu chỉ để cứu vớt những khổ đau, để người khác không phải chiến đấu nữa!\""
  },
  AvgVideoCaption_90244_Content_76 = {
    Text = "Vào lúc hiệp sĩ dứt lời"
  },
  AvgVideoCaption_90244_Content_77 = {
    Text = "Những bóng tối lắc lư như vô số xúc tu và những ảo giác tưởng chừng như thật đã biến mất"
  },
  AvgVideoCaption_90244_Content_78 = {
    Text = "Kẻo một tiếng, kiếm của hiệp sĩ chạm rìu của quái vật, đánh bay cái rìu"
  },
  AvgVideoCaption_90244_Content_79 = {
    Text = "\"Bạn đã chứng minh được lòng nhân từ, sự trung thành và sự thuần khiết của mình.\""
  },
  AvgVideoCaption_90244_Content_8 = {
    Text = "...Bạn nói đúng, để mình giúp bạn xử lý vết thương trước đã"
  },
  AvgVideoCaption_90244_Content_80 = {
    Text = "\"Bây giờ, bạn có thể dẫn công chúa đi.\""
  },
  AvgVideoCaption_90244_Content_81 = {
    Text = "Hồn ma đáng sợ hóa thành một làn khói chậm rãi tan biến"
  },
  AvgVideoCaption_90244_Content_82 = {
    Text = "Chỉ còn lại bộ áo giáp cổ xưa, phủ đầy rỉ xanh"
  },
  AvgVideoCaption_90244_Content_83 = {
    Text = "Hiệp sĩ cúi chào sâu trước bộ áo giáp đó"
  },
  AvgVideoCaption_90244_Content_84 = {
    Text = "Anh ta bước lên cầu thang xoay từng bước từng bước"
