  AvgVideoCaption_90244_Content_9 = {Text = "Ừm!"},
  AvgVideoCaption_90244_Content_90 = {
    Text = "Đúng vậy! Hahaha"
  },
  AvgVideoCaption_90244_Content_91 = {
    Text = "Nghĩ vậy, chỉ cần công chúa dũng mãnh giơ kiếm lên"
