  AvgVideoCaption_90244_Content_92 = {
    Text = "Câu chuyện này không có phần của kỵ sĩ"
  },
  AvgVideoCaption_90244_Content_93 = {
    Text = "Đúng vậy, nhưng lúc này, hiệp sĩ vẫn cứu được công chúa"
  },
  AvgVideoCaption_90244_Content_94 = {
    Text = "Anh ta đưa công chúa lên ngựa, chạy dưới bầu trời sao bao la và mặt trăng tròn"
  },
  AvgVideoCaption_90244_Content_95 = {
