  AvgVideoCaption_96010_Content_104 = {
    Text = "Ghi chép một cách trung thành mỗi hình ảnh mà bạn đã nhìn thấy"
  },
  AvgVideoCaption_96010_Content_105 = {
    Text = "Hãy tận hưởng vinh quang làm một ghoul"
