  AvgVideoCaption_96010_Content_108 = {
    Text = "Vậy thì, bữa tiệc tối vui vẻ nên kết thúc thôi"
  },
  AvgVideoCaption_96010_Content_109 = {
    Text = "Lễ hội cúng linh hồn năm nay, chúng ta nhất định sẽ được chiêm ngưỡng một kiệt tác"
  },
  AvgVideoCaption_96010_Content_11 = {
    Text = "Xin lỗi khi nói thẳng, ông Pickman"
