  },
  AvgVideoCaption_96010_Content_13 = {
    Text = "Tất cả đều là những tác phẩm tầm thường trong quan niệm ngu xuẩn của người đời"
  },
  AvgVideoCaption_96010_Content_14 = {
    Text = "Và đây, cũng chính là lý do tôi mời bạn đến đây"
  },
  AvgVideoCaption_96010_Content_15 = {
    Text = "Ngày lễ lớn của chúng ta cần một bức tranh kiệt xuất"
